const nowUtc = new Date();
const ctStr = nowUtc.toLocaleString('en-US', { timeZone: 'America/Chicago' });
const ctNow = new Date(ctStr);
const target = new Date(ctNow);
target.setDate(target.getDate() - 1);
const y = target.getFullYear();
const m = String(target.getMonth() + 1).padStart(2, '0');
const d = String(target.getDate()).padStart(2, '0');
const target_date_iso = `${y}-${m}-${d}`;
function ctMidnightUtc(dateIso) {
  const utcGuess = new Date(`${dateIso}T00:00:00Z`);
  const ctEquivalent = new Date(utcGuess.toLocaleString('en-US', { timeZone: 'America/Chicago' }));
  const offsetMs = utcGuess.getTime() - ctEquivalent.getTime();
  return new Date(utcGuess.getTime() + offsetMs);
}
const startUtc = ctMidnightUtc(target_date_iso);
const endUtc = new Date(startUtc.getTime() + 24 * 3600 * 1000);
const cumulativeStart = new Date(endUtc.getTime() - 7 * 24 * 3600 * 1000);
const fmt = (dt) => dt.toISOString().replace(/\.\d{3}Z$/, 'Z');
return [{ json: {
  target_date_iso,
  target_start_utc: fmt(startUtc),
  target_end_utc: fmt(endUtc),
  cumulative_start_utc: fmt(cumulativeStart),
  render_now_utc: nowUtc.toISOString()
}}];

function parseLokiResponse(resp) {
  if (!resp || !resp.data) return [];
  const streams = resp.data.result || [];
  const out = [];
  for (const stream of streams) {
    for (const pair of (stream.values || [])) {
      const line = pair[1];
      try { out.push(JSON.parse(line)); } catch (e) {}
    }
  }
  return out;
}
function parseFluxCsv(text) {
  if (!text || typeof text !== 'string') return [];
  const lines = text.split(/\r?\n/).filter(function (l) { return l.length > 0; });
  let headers = null;
  const rows = [];
  for (const line of lines) {
    if (line.startsWith('#')) continue;
    if (!headers) { headers = line.split(','); continue; }
    const fields = line.split(',');
    const row = {};
    for (let i = 0; i < headers.length; i++) {
      const h = (headers[i] || '').trim();
      if (!h || h === 'result' || h === 'table') continue;
      const v = (fields[i] || '').trim();
      const num = Number(v);
      row[h] = (v !== '' && !isNaN(num)) ? num : v;
    }
    rows.push(row);
  }
  return rows;
}
function formatCt(isoTs) {
  if (!isoTs) return '';
  const d = new Date(isoTs);
  if (isNaN(d.getTime())) return String(isoTs);
  return d.toLocaleString('en-US', { timeZone: 'America/Chicago', hour: 'numeric', minute: '2-digit', hour12: true });
}
function isSynthetic(t) { return typeof t.tick_id === 'string' && t.tick_id.startsWith('commission'); }
function tally(events) {
  const c = {};
  for (const e of events) {
    if (typeof e.reason_code === 'string') c[e.reason_code] = (c[e.reason_code] || 0) + 1;
  }
  return c;
}
const dateCtx = $('Compute Target Date').first().json;
const target_date = dateCtx.target_date_iso;
const target_start_utc = dateCtx.target_start_utc;
const target_end_utc = dateCtx.target_end_utc;
const queryErrors = [];
function checkError(name, item) {
  const j = item && item.json;
  if (j && j.statusCode && j.statusCode >= 400) {
    queryErrors.push({ query: name, status: j.statusCode });
  }
}
const lokiTargetItem = $('Loki Target Day Traces').first();
checkError('loki_target_day', lokiTargetItem);
const targetTraces = parseLokiResponse(lokiTargetItem.json);
const loki7dItem = $('Loki 7d Trace Counts').first();
checkError('loki_7d', loki7dItem);
const traces7d = parseLokiResponse(loki7dItem.json);
if (traces7d.length >= 5000) queryErrors.push({ query: 'loki_7d', warn: 'limit_saturated', note: 'observed counts may be truncated at 5000 entries' });
const organic7d = traces7d.filter(function (t) { return !isSynthetic(t); });
const synthetic7d = traces7d.filter(isSynthetic);
const observed_reason_codes_7d_organic = tally(organic7d);
const observed_reason_codes_7d_synthetic = tally(synthetic7d);

// Observability: earliest decision_trace.* timestamp visible in our 7d window
let trace_first_seen_ms = null;
for (const t of traces7d) {
  const ms = new Date(t.ts).getTime();
  if (!isNaN(ms) && (trace_first_seen_ms === null || ms < trace_first_seen_ms)) {
    trace_first_seen_ms = ms;
  }
}
const trace_first_seen_utc = trace_first_seen_ms !== null ? new Date(trace_first_seen_ms).toISOString().replace(/\.\d{3}Z$/, 'Z') : null;
const target_start_ms = new Date(target_start_utc).getTime();
const target_end_ms = new Date(target_end_utc).getTime();
