if (trace_first_seen_ms === null) {
  coverage = 'none';
  observability_notes.push('No decision_trace events visible in the 7d window. Treat absence of trace for any target-day event as observability gap, not controller non-response.');
} else if (trace_first_seen_ms <= target_start_ms) {
  coverage = 'full';
} else if (trace_first_seen_ms < target_end_ms) {
  coverage = 'partial';
  observability_notes.push('decision_trace logging started partway through the target day. Missing traces BEFORE decision_trace_first_seen_utc are observability gaps, not controller non-response evidence. Use the hvac.* Influx audit rows as the canonical record for that earlier window.');
} else {
