const dayTypeTraces = targetTraces.filter(function (t) { return t.msg === 'decision_trace.day_type_decision' && t.decision_for_date === target_date; });
const precoolTraces = targetTraces.filter(function (t) { return t.msg === 'decision_trace.precool_decision' && t.decision_for_date === target_date; });
