const FIVE_MIN_MS = 5 * 60 * 1000;
const FIFTEEN_MIN_MS = 15 * 60 * 1000;
const price_spikes = spikeRowsRaw.map(function (r) {
  const spikeMs = new Date(r._time).getTime();
  const nearbyTraces = overlayTraces.filter(function (t) {
    const tMs = new Date(t.ts).getTime();
    return !isNaN(tMs) && Math.abs(tMs - spikeMs) <= FIVE_MIN_MS;
  }).map(function (t) { return { time_ct: formatCt(t.ts), reason_code: t.reason_code, prev_tier: t.prev_tier, new_tier: t.new_tier, outcome: t.outcome }; });
  const nearbyAudit = priceOverlayAuditRows.filter(function (a) {
    const aMs = new Date(a._time).getTime();
    return !isNaN(aMs) && aMs >= spikeMs && (aMs - spikeMs) <= FIFTEEN_MIN_MS;
  }).map(function (a) {
    return {
      time_ct: formatCt(a._time),
      time_utc: a._time,
      lag_seconds: Math.round((new Date(a._time).getTime() - spikeMs) / 1000),
      prev_tier: a.prev_tier,
      new_tier: a.new_tier,
      current_price_cents: a.current_price_cents,
