  });
  return {
    time_ct: formatCt(r._time),
    price_cents_per_kwh: r.price_cents,
    nearby_decision_trace_within_5m: nearbyTraces,
    nearby_hvac_price_overlay_audit_within_15m_forward: nearbyAudit,
  };
});

const normalTraces = layerSupTraces.filter(function (t) { return !isSynthetic(t); }).map(function (t) { return Object.assign({ time_ct: formatCt(t.ts) }, t); });
const syntheticTraces = layerSupTraces.filter(isSynthetic).map(function (t) { return Object.assign({ time_ct: formatCt(t.ts) }, t); });

const FEED_SPEC = [
  { name: 'comed.prices',       kind: 'continuous' },
  { name: 'nws.forecast',       kind: 'continuous' },
  { name: 'pjm.lmp_da_hourly',  kind: 'event',        expected_cadence: 'daily ~17:00 CT' },
  { name: 'pjm.inst_load',      kind: 'continuous' },
