for (const r of feedRows) { if (r._measurement) feedMap[r._measurement] = r._time; }
const feed_health_now = FEED_SPEC.map(function (spec) {
  const lastWrite = feedMap[spec.name] || null;
  const out = { name: spec.name, kind: spec.kind, last_write: lastWrite, has_data: lastWrite !== null };
  if (spec.expected_cadence) out.expected_cadence = spec.expected_cadence;
